export const TRICK_KEY = "bluegill";
export const TRICKS = ["platehover", "colonyfan", "insectpeck", "gillflare", "opercle", "earflap", "macrochirus"] as const;
export const HAPPY = ["denspenny", "inkpenny", "densplate"] as const;
export type BluegillTrickKind = (typeof TRICKS)[number];
export type BluegillHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type BluegillTrick = {
  kind: BluegillTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type BluegillHappy = {
  kind: BluegillHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { denspenny: 1.70, inkpenny: 1.84, densplate: 1.76 } as const;
export const MACROCHIRUS_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  macrochirus: MACROCHIRUS_HOLD + RELEASE_S,
  platehover: 2.48,
  colonyfan: 2.42,
  insectpeck: 2.56,
  gillflare: 2.44,
  opercle: 2.40,
  earflap: 2.38,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: BluegillTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "macrochirus") return 40 + roll * 26;
  if (kind === "opercle" || kind === "earflap" || kind === "platehover") return 12.8 + roll * 9.4;
  if (kind === "colonyfan" || kind === "insectpeck" || kind === "gillflare") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

